import{_ as a,o as s,c as i,a2 as n}from"./chunks/framework.BsAvorgW.js";const u=JSON.parse('{"title":"接入程序","description":"","frontmatter":{},"headers":[],"relativePath":"guide/use.md","filePath":"guide/use.md","lastUpdated":1784136889000}'),t={name:"guide/use.md"};function l(r,e,p,o,d,c){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="接入程序" tabindex="-1">接入程序 <a class="header-anchor" href="#接入程序" aria-label="Permalink to &quot;接入程序&quot;">​</a></h1><h2 id="通用代理地址" tabindex="-1">通用代理地址 <a class="header-anchor" href="#通用代理地址" aria-label="Permalink to &quot;通用代理地址&quot;">​</a></h2><p>在 WebUI 的 <strong>链接</strong> 页面复制账号对应的地址：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://用户名:密码@服务器地址:17891</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>将它填入调用方的 HTTP 代理配置。目标地址必须位于 SelenaProxy 的域名和端口白名单中。</p><h2 id="使用-curl-测试" tabindex="-1">使用 curl 测试 <a class="header-anchor" href="#使用-curl-测试" aria-label="Permalink to &quot;使用 curl 测试&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://用户名:密码@服务器地址:17891&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://目标域名</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>常见返回：</p><ul><li><code>200 Connection Established</code>：代理隧道建立成功。</li><li><code>407 Proxy Authentication Required</code>：用户名、密码或账号状态有问题。</li><li><code>403 Target Not Allowed</code>：目标域名或端口不在白名单。</li><li><code>502 All Upstream Proxies Failed</code>：供应商或短效节点连接失败。</li></ul><h2 id="配合-xutheringwavesuid" tabindex="-1">配合 XutheringWavesUID <a class="header-anchor" href="#配合-xutheringwavesuid" aria-label="Permalink to &quot;配合 XutheringWavesUID&quot;">​</a></h2><p>SelenaProxy 可以作为 <a href="https://github.com/Loping151/XutheringWavesUID" target="_blank" rel="noreferrer">XutheringWavesUID</a> 请求游戏接口时使用的 HTTP 代理。</p><ol><li>在 SelenaProxy 中允许 XutheringWavesUID 实际访问的接口域名与 <code>443</code> 端口。</li><li>单独创建一个账号，方便查看插件使用量。</li><li>复制完整代理链接。</li><li>将链接填入 XutheringWavesUID 对应的代理配置项。</li></ol><p>不同版本的 XutheringWavesUID 配置名称可能调整，请以它当前控制台显示的配置项为准。</p><h2 id="多服务器使用" tabindex="-1">多服务器使用 <a class="header-anchor" href="#多服务器使用" aria-label="Permalink to &quot;多服务器使用&quot;">​</a></h2><p>推荐每台服务器建立一个账号，例如：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>官服机器人 → account-official</span></span>
<span class="line"><span>测试机器人 → account-test</span></span>
<span class="line"><span>个人脚本   → account-personal</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这样可以直接在 WebUI 中判断是哪台设备产生了失败或异常流量。</p>`,17)])])}const b=a(t,[["render",l]]);export{u as __pageData,b as default};
